// Some portions generated by Claude

// Every rendered resource, whether shown by prefixed name, full IRI or label, carries the full IRI as its title.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');
const { renderPageResultTables } = require('./page-result-table-harness.js');
const { createExploreModel } = require('./explore-section-fixtures.js');

const scripts = require('./workbench-scripts.js').compiledScriptsDir();

function loadViews() {
    const window = { location: { href: 'http://x.test/workbench/repositories/r/explore', search: '' } };
    const workbench = {};
    installDetailDisclosureTemplateRuntime(workbench);
    const context = vm.createContext({ console, URL, URLSearchParams, Promise, window, workbench, setTimeout });
    for (const filename of ['workbenchViews.js', 'workbenchRoutes.js', 'queryStream.js', 'workbenchApp.js']) {
        vm.runInContext(fs.readFileSync(path.join(scripts, filename), 'utf8'), context, { filename });
    }
    return context.workbench;
}

function flat(template) {
    if (Array.isArray(template)) { return template.map(flat).join(''); }
    if (template && Array.isArray(template.strings)) {
        return template.strings.map((part, index) => part
            + (index < template.values.length ? flat(template.values[index]) : '')).join('');
    }
    return template == null || typeof template === 'function' ? '' : String(template);
}

const ctx = { basePath: '/workbench', repositoryId: 'r', workbench: {} };
const IRI = 'http://example.org/ns#thing';
const iri = (value) => ({ kind: 'iri', value });
const namespaces = { 'ex:': 'http://example.org/ns#' };

test('the Explore heading and section links show the full IRI as a title', async () => {
    const wb = loadViews();
    const model = createExploreModel({
        namespaceMap: namespaces,
        metadata: { resource: '<' + IRI + '>', 'explore-resource': '<' + IRI + '>' },
        sections: {
            label: { rows: [[{ kind: 'literal', value: 'A thing' }]] },
            types: { rows: [[iri(IRI)]] }
        }
    });
    const page = await renderPageResultTables(wb, model, ctx);
    const markup = flat(page.template);
    assert.ok(markup.includes(`<h2 title=${IRI}>A thing</h2>`), markup.slice(0, 600));
    assert.match(markup, new RegExp(`<a href=[^>]*title=${IRI}>[^<]*</a>`), 'section links carry the full IRI');
});

test('a result table anchor shows the full IRI as a title', async () => {
    const wb = loadViews();
    const rows = [[iri(IRI), iri('urn:p'), iri('urn:o'), null]];
    const model = createExploreModel({
        namespaceMap: namespaces,
        metadata: { resource: '<' + IRI + '>', 'explore-resource': '<' + IRI + '>' },
        sections: { outgoing: { rows, totalRows: 1, count: '1' } }
    });
    const page = await renderPageResultTables(wb, model, ctx);
    const table = page.markup('explore-outgoing');
    assert.match(table, new RegExp(`<a href="explore\\?resource=[^"]*" title="urn:p"`), table.slice(0, 800));
});
